        {
          delay: 750,
          beam: { from: "writer", to: "seo" },
          update: (prev) => ({
            ...prev,
            "fact-checker": { status: "done", tokens: 24000, activity: "All 8 verified", glow: false },
            writer: { status: "working", tokens: 84000, activity: "Optimizing copy", glow: false },
          }),
        },
        // 9: SEO working
        {
          delay: 1200,
          beam: null,
          update: (prev) => ({
            ...prev,
            seo: { status: "working", tokens: 12000, activity: "Scoring keywords", glow: true },
          }),
        },
        // 10: SEO done, Writer done -> returns to Editor
        {
          delay: 850,
          beam: { from: "writer", to: "editor" },
          update: (prev) => ({
            ...prev,
            seo: { status: "done", tokens: 16000, activity: "Score 96/100", glow: false },
            writer: { status: "done", tokens: 102000, activity: "Draft ready", glow: false },
          }),
        },
        // 11: Settled State: Editor enters "Needs you"
        {
          delay: 3400,
          beam: null,
          update: (prev) => ({
            ...prev,
            editor: { status: "needs-you", tokens: 48000, activity: "Publish launch post?", glow: true },
          }),
        },
      ];

      const activeSchedule = variant === "editorial" ? editorialSchedule : schedule;

      if (simStep === 0) {
        setUserOverrides({});
      }

      const current = activeSchedule[simStep % activeSchedule.length];
      setActiveBeam(current.beam ?? null);
      setAgentStates(current.update);

      const timer = setTimeout(() => {
        setSimStep((prev) => (prev + 1) % activeSchedule.length);
      }, current.delay);

      return () => clearTimeout(timer);
    }, [simStep, liveAnimation, variant]);

    const rootPalette = AGENT_COLORS[data.color] ?? AGENT_COLORS.blue;
    const children = data.children ?? [];
    const colCount = children.length;

    const leadState = effectiveStates[data.id] || {
      status: data.status,
      tokens: data.tokensUsed,
      activity: data.message,
      glow: false,
    };

    const leftChildId = children[0]?.id;
    const middleChildId = colCount >= 3 ? children[1]?.id : undefined;
    const rightChildId = colCount >= 2 ? children[colCount - 1]?.id : undefined;

    // Determine beam active flags for desktop SVG dynamically
    const isBeamToLeft = activeBeam?.from === data.id && activeBeam?.to === leftChildId;
    const isBeamReturnFromLeft = activeBeam?.from === leftChildId && activeBeam?.to === data.id;
    const isBeamToMiddle = Boolean(middleChildId) && activeBeam?.from === data.id && activeBeam?.to === middleChildId;
    const isBeamToRight = Boolean(rightChildId) && activeBeam?.from === data.id && activeBeam?.to === rightChildId;
    const isBeamReturnFromRight = Boolean(rightChildId) && activeBeam?.from === rightChildId && activeBeam?.to === data.id;

    const trunkRef = useRef<HTMLDivElement>(null);
    const [trunkWidth, setTrunkWidth] = useState<number>(840);

    useEffect(() => {
      const el = trunkRef.current;
      if (!el) return;
      const updateWidth = () => {
        if (el.clientWidth > 0) setTrunkWidth(el.clientWidth);
      };
      updateWidth();
      const ro = new ResizeObserver(updateWidth);
      ro.observe(el);
      return () => ro.disconnect();
    }, []);

    // Exact 1:1 pixel coordinates for 3-column grid with gap-5 (20px)
    const gapPx = 20;
    const colW = colCount > 0 ? (trunkWidth - gapPx * (colCount - 1)) / colCount : trunkWidth;
    const centerX = trunkWidth / 2;
    const leftX = colCount >= 1 ? colW / 2 : centerX;
    const rightX = colCount >= 2 ? (colCount - 1) * (colW + gapPx) + colW / 2 : centerX;
    const r = 8;

    const leftPath = `M ${centerX},0 V ${16 - r} Q ${centerX},16 ${centerX - r},16 H ${leftX + r} Q ${leftX},16 ${leftX},${16 + r} V 32`;
    const middlePath = `M ${centerX},0 V 32`;
    const rightPath = `M ${centerX},0 V ${16 - r} Q ${centerX},16 ${centerX + r},16 H ${rightX - r} Q ${rightX},16 ${rightX},${16 + r} V 32`;

    return (
      <div
        ref={ref}
        className={cn(
          "w-full max-w-[920px] mx-auto select-none",
          animateIn && "animate-in fade-in duration-500",
          className,
        )}
        {...props}
      >
        {/* Agent Graph CSS Keyframes & Live Effects */}
        <style dangerouslySetInnerHTML={{
          __html: `
            @keyframes agentGraphIn {
              from { opacity: 0; transform: translateY(6px) scale(0.98); }
            }
            @keyframes agentGraphDraw {
              from { stroke-dashoffset: 1; }
              to { stroke-dashoffset: 0; }
            }
            @keyframes agentGraphPixel {
              0%, 100% { opacity: 1; }
              50% { opacity: 0.2; }
            }
            @keyframes agentGraphShine {
              from { background-position: 100% 0; }
              to { background-position: 0 0; }
            }
            @keyframes agentGraphGlowFade {
              0%, 30% { opacity: 1; }
              100% { opacity: 0; }
            }
            @keyframes agentGraphGlowRise {
              0% { transform: translate(0, 0) scale(1, 1); }
              100% { transform: translate(0, -25%) scale(1.08, 1.8); }
            }
            @keyframes agentGraphGlowFromTop {
              0% { transform: translate(0, 0) scale(1, 1); }
              100% { transform: translate(0, 25%) scale(1.08, 1.8); }
            }
            @keyframes agentGraphGlowFromLeft {
              0% { transform: translate(0, 0) scale(1, 1); }
              100% { transform: translate(25%, 0) scale(1.8, 1.08); }
            }
            @keyframes agentGraphBeamTravel {
              0% { stroke-dashoffset: 28; opacity: 0; }
              12% { opacity: 1; }
              88% { opacity: 1; }
              100% { stroke-dashoffset: -100; opacity: 0; }
            }
            @keyframes agentGraphBeamReturn {
              0% { stroke-dashoffset: -100; opacity: 0; }
              12% { opacity: 1; }
              88% { opacity: 1; }
              100% { stroke-dashoffset: 28; opacity: 0; }
            }
            .agent-graph-activity-live {
              background: linear-gradient(90deg, #52525b 0%, #18181b 50%, #52525b 100%) 100% 0 / 260% 100%;
              -webkit-background-clip: text;
              background-clip: text;
              -webkit-text-fill-color: transparent;
              animation: agentGraphShine 2s linear infinite;
            }
            .dark .agent-graph-activity-live {
              background: linear-gradient(90deg, #a1a1aa 0%, #f4f4f5 50%, #a1a1aa 100%) 100% 0 / 260% 100%;
              -webkit-background-clip: text;
              background-clip: text;
              -webkit-text-fill-color: transparent;
              animation: agentGraphShine 2s linear infinite;
            }
            .agent-graph-mark-busy i {
              animation: agentGraphPixel 1.2s ease-in-out infinite both;
            }
          `
        }} />

        {/* Root Node (Lead) */}
        <div className="w-full md:w-[272px] md:mx-auto">
          <AgentCard
            node={data}
            anchorPosition="center-desktop-left-mobile"
            shade={shade}
            isOpen={openCardId === data.id}
            onToggleOpen={() =>
              setOpenCardId(openCardId === data.id ? null : data.id)
            }
            isWorking={leadState.status === "working"}
            isDone={leadState.status === "done"}
            isPaused={leadState.status === "paused"}
            isWaiting={leadState.status === "needs-you"}
            hasArrivalGlow={leadState.glow}
            arrivalSide="bottom"
            tokensCurrent={leadState.tokens}
            liveActivityText={leadState.activity}
            onPause={() => handleAgentAction(data.id, "pause")}
            onResume={() => handleAgentAction(data.id, "resume")}
            onStop={() => handleAgentAction(data.id, "stop")}
            onApprove={() => handleAgentAction(data.id, "approve")}
            onDecline={() => handleAgentAction(data.id, "decline")}
          />
        </div>

        {/* Mobile Vertical Tree (< md) */}
        {colCount > 0 && (
          <div className="md:hidden">
            <SubAgentBranch
              nodes={children}
              lineColor={rootPalette.hex}
              compact={false}
              shade={shade}
              openCardId={openCardId}
              setOpenCardId={setOpenCardId}
              stateMap={effectiveStates}
              activeBeam={activeBeam}
              onAgentAction={handleAgentAction}
              renderNode={(child) => {
                const childPalette =
                  AGENT_COLORS[child.color] ?? AGENT_COLORS.blue;
                const s = effectiveStates[child.id] || {
                  status: child.status,
                  tokens: child.tokensUsed,
                  activity: child.message,
                  glow: false,
                };

                return (
                  <div>
                    <AgentCard
                      node={child}
                      shade={shade}
                      isOpen={openCardId === child.id}
                      onToggleOpen={() =>
                        setOpenCardId(openCardId === child.id ? null : child.id)
                      }
                      isWorking={s.status === "working"}
                      isDone={s.status === "done"}
                      isPaused={s.status === "paused"}
                      isWaiting={s.status === "needs-you"}
                      hasArrivalGlow={s.glow}
                      arrivalSide="top"
                      tokensCurrent={s.tokens}
                      liveActivityText={s.activity}
                      onPause={() => handleAgentAction(child.id, "pause")}
                      onResume={() => handleAgentAction(child.id, "resume")}
                      onStop={() => handleAgentAction(child.id, "stop")}
                      onApprove={() => handleAgentAction(child.id, "approve")}
                      onDecline={() => handleAgentAction(child.id, "decline")}
                    />
                    {child.children && child.children.length > 0 && (
                      <SubAgentBranch
                        nodes={child.children}
                        lineColor={childPalette.hex}
                        shade={shade}
                        openCardId={openCardId}
                        setOpenCardId={setOpenCardId}
                        stateMap={effectiveStates}
                        activeBeam={activeBeam}
                        onAgentAction={handleAgentAction}
                      />
                    )}
                  </div>
                );
              }}
            />
          </div>
        )}

        {/* Desktop Horizontal Multi-Column Tree (>= md) */}
        {colCount > 0 && (
          <div className={cn("hidden md:block", colCount === 2 && "max-w-[600px] mx-auto")}>
            {/* SVG Connector Trunk between Root and Columns (1:1 CSS pixel space) */}
            <div ref={trunkRef} className="relative w-full h-8 pointer-events-none">
              <svg
                className="w-full h-full overflow-visible"
                viewBox={`0 0 ${trunkWidth} 32`}
              >
                {/* Center origin dot under Root */}
                <circle
                  cx={centerX}
                  cy="0"
                  r="3"
                  className="fill-white dark:fill-zinc-950"
                  stroke="#0190fe"
                  strokeWidth="1.5"
                />

                {/* Base neutral connector rails */}
                {/* Left Branch Rail (Root to Col 0) */}
                <path
                  d={leftPath}
                  stroke="currentColor"
                  strokeWidth="1.5"
                  strokeLinecap="round"
                  fill="none"
                  className={cn(
                    "transition-opacity duration-500",
                    isBeamToLeft || isBeamReturnFromLeft
                      ? "text-blue-500/50 opacity-90"
                      : "text-neutral-300 dark:text-zinc-700 opacity-60",
                  )}
                />
                {/* Middle Branch Rail (Root to middle column when 3+ cols) */}
                {colCount >= 3 && (
                  <path
                    d={middlePath}
                    stroke="currentColor"
                    strokeWidth="1.5"
                    strokeLinecap="round"
                    fill="none"
                    className={cn(
                      "transition-opacity duration-500",
                      isBeamToMiddle
                        ? "text-blue-500/50 opacity-90"
                        : "text-neutral-300 dark:text-zinc-700 opacity-60",
                    )}
                  />
                )}
                {/* Right Branch Rail (Lead to Col 2) */}
                <path
                  d={rightPath}
                  stroke="currentColor"
                  strokeWidth="1.5"
                  strokeLinecap="round"
                  fill="none"
                  className={cn(
                    "transition-opacity duration-500",
                    isBeamToRight || isBeamReturnFromRight
                      ? "text-blue-500/50 opacity-90"
                      : "text-neutral-300 dark:text-zinc-700 opacity-60",
                  )}
                />

                {/* TRAVELING HANDOFF LIGHT: Lead -> Researcher (Left) */}
                {isBeamToLeft && (
                  <path
                    d={leftPath}
                    stroke="#0190fe"
                    strokeWidth="1.5"
                    strokeLinecap="round"
                    fill="none"
                    pathLength="100"
                    strokeDasharray="28 130"
                    className="animate-[agentGraphBeamTravel_0.85s_cubic-bezier(0.32,0.72,0.24,1)_forwards]"
                    style={{
                      filter: "drop-shadow(0 0 1.5px rgba(1,144,254,0.45))",
                    }}
                  />
                )}

                {/* RETURN HANDOFF LIGHT: Researcher -> Lead */}
                {isBeamReturnFromLeft && (
                  <path
                    d={leftPath}
                    stroke="#a855f7"
                    strokeWidth="1.5"
                    strokeLinecap="round"
                    fill="none"
                    pathLength="100"
                    strokeDasharray="28 130"
                    className="animate-[agentGraphBeamReturn_0.85s_cubic-bezier(0.32,0.72,0.24,1)_forwards]"
                    style={{
                      filter: "drop-shadow(0 0 1.5px rgba(168,85,247,0.45))",
                    }}
                  />
                )}

                {/* TRAVELING HANDOFF LIGHT: Lead -> Coder (Middle) */}
                {isBeamToMiddle && (
                  <path
                    d={middlePath}
                    stroke="#0190fe"
                    strokeWidth="1.5"
                    strokeLinecap="round"
                    fill="none"
                    pathLength="100"
                    strokeDasharray="28 130"
                    className="animate-[agentGraphBeamTravel_0.8s_cubic-bezier(0.32,0.72,0.24,1)_forwards]"
                    style={{
                      filter: "drop-shadow(0 0 1.5px rgba(1,144,254,0.45))",
                    }}
                  />
                )}

                {/* TRAVELING HANDOFF LIGHT: Lead -> Reviewer (Right) */}
                {isBeamToRight && (
                  <path
                    d={rightPath}
                    stroke="#0190fe"
                    strokeWidth="1.5"
                    strokeLinecap="round"
                    fill="none"
                    pathLength="100"
                    strokeDasharray="28 130"
                    className="animate-[agentGraphBeamTravel_0.85s_cubic-bezier(0.32,0.72,0.24,1)_forwards]"
                    style={{
                      filter: "drop-shadow(0 0 1.5px rgba(1,144,254,0.45))",
                    }}
                  />
                )}

                {/* RETURN HANDOFF LIGHT: Reviewer -> Lead */}
                {isBeamReturnFromRight && (
                  <path
                    d={rightPath}
                    stroke="#10b981"
                    strokeWidth="1.5"
                    strokeLinecap="round"
                    fill="none"
                    pathLength="100"
                    strokeDasharray="28 130"
                    className="animate-[agentGraphBeamReturn_0.85s_cubic-bezier(0.32,0.72,0.24,1)_forwards]"
                    style={{
                      filter: "drop-shadow(0 0 1.5px rgba(16,185,129,0.45))",
                    }}
                  />
                )}
              </svg>
            </div>

            {/* 3 Columns Grid */}
            <div
              className="grid gap-5"
              style={{
                gridTemplateColumns: `repeat(${colCount}, minmax(0, 1fr))`,
              }}
            >
              {children.map((child) => {
                const childPalette =
                  AGENT_COLORS[child.color] ?? AGENT_COLORS.blue;
                const s = effectiveStates[child.id] || {
                  status: child.status,
                  tokens: child.tokensUsed,
                  activity: child.message,
                  glow: false,
                };

                return (
                  <div key={child.id} className="relative flex flex-col">
                    {/* Level 1 Card */}
                    <AgentCard
                      node={child}
                      shade={shade}
                      isOpen={openCardId === child.id}
                      onToggleOpen={() =>
                        setOpenCardId(openCardId === child.id ? null : child.id)
                      }
                      isWorking={s.status === "working"}
                      isDone={s.status === "done"}
                      isPaused={s.status === "paused"}
                      isWaiting={s.status === "needs-you"}
                      hasArrivalGlow={s.glow}
                      arrivalSide="top"
                      tokensCurrent={s.tokens}
                      liveActivityText={s.activity}
                      onPause={() => handleAgentAction(child.id, "pause")}
                      onResume={() => handleAgentAction(child.id, "resume")}
                      onStop={() => handleAgentAction(child.id, "stop")}
                      onApprove={() => handleAgentAction(child.id, "approve")}
                      onDecline={() => handleAgentAction(child.id, "decline")}
                    />

                    {/* Level 2 Sub-Agents */}
                    {child.children && child.children.length > 0 && (
                      <SubAgentBranch
                        nodes={child.children}
                        lineColor={childPalette.hex}
                        shade={shade}
                        openCardId={openCardId}
                        setOpenCardId={setOpenCardId}
                        stateMap={effectiveStates}
                        activeBeam={activeBeam}
                        onAgentAction={handleAgentAction}
                      />
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    );
  },
);
AgentGraph.displayName = "AgentGraph";

"use client";

/**
 * Animated icons: the Lucide glyph set, each with a short hand-tuned motion that
 * plays when the control around it is hovered or focused (or when it first
 * appears, for state-change icons such as a check).
 *
 * Dependency-free on purpose. Motion runs on the Web Animations API, so the icons
 * work in any component whatever animation library it uses (GSAP or Motion),
 * add no npm package, and stand still under `prefers-reduced-motion`.
 *
 * Use them exactly like Lucide icons:
 *   <ChevronDownIcon className="size-4" />
 * They animate with the closest button, link, tab, menu item or label, or on
 * their own hover when there is none. Pass `animated={false}` to keep one still,
 * `animateOnMount` to play it once as it appears.
 *
 * To add an icon, copy its node list from lucide-react (`__iconData.node`) into a
 * `defineIcon(...)` call with the preset that suits it (see DESIGN.md, Icons).
 */
import {
  createElement,
  forwardRef,
  useCallback,
  useEffect,
  useRef,
  type ComponentType,
  type SVGProps,
} from "react";
import { prefersReducedMotion } from "@/lib/animate";
import { cn } from "@/lib/utils";

export type IconProps = Omit<SVGProps<SVGSVGElement>, "ref"> & {
  size?: number | string;
  strokeWidth?: number | string;
  /** Play the motion on hover or focus. Default true. */
  animated?: boolean;
  /** Also play it once when the icon mounts, for icons that mark a state change. */
  animateOnMount?: boolean;
};

/** Anything that renders like an icon: these, or a Lucide icon. */
export type IconComponent = ComponentType<IconProps>;

type IconNode = [tag: string, attrs: Record<string, string>][];

const SOFT = "cubic-bezier(0.22, 1, 0.36, 1)";

const move = (x: string, y = "0") => `translate(${x}, ${y})`;

type Preset = {
  frames: Keyframe[];
  duration: number;
  /** Draw each shape in with a stroke instead of moving the whole icon. */
  draw?: boolean;
};

const PRESETS = {
  nudgeRight: { duration: 650, frames: [{ transform: move("0") }, { transform: move("18%") }, { transform: move("0") }] },
  nudgeLeft: { duration: 650, frames: [{ transform: move("0") }, { transform: move("-18%") }, { transform: move("0") }] },
  nudgeUp: { duration: 650, frames: [{ transform: move("0") }, { transform: move("0", "-18%") }, { transform: move("0") }] },
  nudgeDown: { duration: 650, frames: [{ transform: move("0") }, { transform: move("0", "18%") }, { transform: move("0") }] },
  float: { duration: 700, frames: [{ transform: move("0") }, { transform: move("14%", "-14%") }, { transform: move("0") }] },
  spin: { duration: 800, frames: [{ transform: "rotate(0deg)" }, { transform: "rotate(360deg)" }] },
  spinBack: { duration: 800, frames: [{ transform: "rotate(0deg)" }, { transform: "rotate(-360deg)" }] },
  spinSlow: { duration: 1200, frames: [{ transform: "rotate(0deg)" }, { transform: "rotate(180deg)" }] },
  wiggle: {
    duration: 750,
    frames: [0, -14, 12, -8, 4, 0].map((deg) => ({ transform: `rotate(${deg}deg)` })),
  },
  shake: {
    duration: 520,
    frames: [0, -9, 9, -6, 6, 0].map((x) => ({ transform: move(`${x}%`) })),
  },
  pop: {
    duration: 600,
    frames: [{ transform: "scale(1)" }, { transform: "scale(0.8)" }, { transform: "scale(1.18)" }, { transform: "scale(1)" }],
  },
  pulse: { duration: 650, frames: [{ transform: "scale(1)" }, { transform: "scale(1.14)" }, { transform: "scale(1)" }] },
  pulseBeat: {
    duration: 700,
    frames: [{ transform: "scale(1)" }, { transform: "scale(1.2)" }, { transform: "scale(0.96)" }, { transform: "scale(1)" }],
  },
  bounce: {
    duration: 750,
    frames: [0, -20, 0, -8, 0].map((y) => ({ transform: move("0", `${y}%`) })),
  },
  tilt: {
    duration: 650,
    frames: [{ transform: "rotate(0deg)" }, { transform: "rotate(-14deg)" }, { transform: "rotate(8deg)" }, { transform: "rotate(0deg)" }],
  },
  tiltUp: {
    duration: 650,
    frames: [
      { transform: "rotate(0deg) translateY(0)" },
      { transform: "rotate(-14deg) translateY(-10%)" },
      { transform: "rotate(6deg) translateY(0)" },
      { transform: "rotate(0deg) translateY(0)" },
    ],
  },
  tiltDown: {
    duration: 650,
    frames: [
      { transform: "rotate(0deg) translateY(0)" },
      { transform: "rotate(12deg) translateY(10%)" },
      { transform: "rotate(-6deg) translateY(0)" },
      { transform: "rotate(0deg) translateY(0)" },
    ],
  },
  flash: {
    duration: 600,
    frames: [
      { transform: "scale(1)", opacity: 1 },
      { transform: "scale(1.16)", opacity: 0.55 },
      { transform: "scale(1)", opacity: 1 },
    ],
  },
  draw: {
    duration: 650,
    draw: true,
    frames: [
      { strokeDasharray: "1 1", strokeDashoffset: "1", opacity: 0 },
      { strokeDasharray: "1 1", strokeDashoffset: "1", opacity: 1, offset: 0.02 },
      { strokeDasharray: "1 1", strokeDashoffset: "0", opacity: 1 },
    ],
  },
  none: { duration: 0, frames: [] },
} satisfies Record<string, Preset>;

export type IconPreset = keyof typeof PRESETS;

/** What an icon animates with: the control around it, else the icon itself. */
const HOST =
  'button, a, label, summary, [role="button"], [role="tab"], [role="menuitem"], [role="option"], [data-icon-host]';

const play = (svg: SVGSVGElement, preset: Preset) => {
  if (!preset.frames.length || prefersReducedMotion() || typeof svg.animate !== "function") return;
  if (svg.getAnimations({ subtree: true }).some((a) => a.playState === "running")) return;
  if (preset.draw) {
    Array.from(svg.children).forEach((shape, i) =>
      shape.animate(preset.frames, { duration: preset.duration, delay: i * 90, easing: SOFT, fill: "backwards" }),
    );
    return;
  }
  svg.animate(preset.frames, { duration: preset.duration, easing: SOFT });
};

function defineIcon(name: string, presetName: IconPreset, nodes: IconNode): IconComponent {
  const preset: Preset = PRESETS[presetName];

  const Icon = forwardRef<SVGSVGElement, IconProps>(function AnimatedIcon(
    {
      size = 24,
      strokeWidth = 2,
      color = "currentColor",
      className,
      animated = true,
      animateOnMount = false,
      style,
      children,
      ...rest
    },
    forwardedRef,
  ) {
    const svgRef = useRef<SVGSVGElement | null>(null);
    const setRef = useCallback(
      (node: SVGSVGElement | null) => {
        svgRef.current = node;
        if (typeof forwardedRef === "function") forwardedRef(node);
        else if (forwardedRef) forwardedRef.current = node;
      },
      [forwardedRef],
    );

    useEffect(() => {
      const svg = svgRef.current;
      if (!svg || !animated || !preset.frames.length) return;
      const host = svg.closest<HTMLElement>(HOST) ?? svg;
      const run = () => play(svg, preset);
      const onFocus = () => {
        if (host.matches(":focus-visible")) run();
      };
      host.addEventListener("pointerenter", run);
      host.addEventListener("focusin", onFocus);
      const frame = animateOnMount ? requestAnimationFrame(run) : 0;
      return () => {
        host.removeEventListener("pointerenter", run);
        host.removeEventListener("focusin", onFocus);
        if (frame) cancelAnimationFrame(frame);
      };
    }, [animated, animateOnMount]);

    const labelled = rest["aria-label"] !== undefined || rest["aria-labelledby"] !== undefined;

    return (
      <svg
        ref={setRef}
        xmlns="http://www.w3.org/2000/svg"
        width={size}
        height={size}
        viewBox="0 0 24 24"
